action.mutation:
mutation CreateWiki($payload: [WikiCreatePayloadInput!]!) {
  mutation: createWiki(payload: $payload) { 
    id
    name
  }
}

mutation UpdateWiki($payload: [WikiUpdatePayloadInput!]!) {
  mutation: updateWiki(payload: $payload) { 
    id
    name
  }
}

mutation DeleteWiki($payload: [WikiDeletePayloadInput!]!) {
  mutation: deleteWiki(payload: $payload) { 
    id
    name
  }
}
